import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const [useMockMode, setUseMockMode] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Check if we should use mock mode
    const savedMockMode = localStorage.getItem('useMockMode');
    if (savedMockMode !== null) {
      setUseMockMode(savedMockMode === 'true');
    }
  }, []);

  const toggleMockMode = () => {
    const newMode = !useMockMode;
    setUseMockMode(newMode);
    localStorage.setItem('useMockMode', newMode.toString());
    alert(`✅ ${newMode ? 'Mock Mode' : 'Real Backend Mode'} Activated!\n\n` +
          (newMode ? 
            'You can now test all features without backend:\n' +
            '• Create room as Host\n' +
            '• Join as Participant\n' +
            '• Real-time sync between tabs\n' +
            '• Role assignment (Make Moderator/Demote)\n' +
            '• Remove participants\n' +
            '• Seek, Play, Pause, Change Video\n' +
            '• Chat between users\n\n' +
            'Open multiple browser tabs to test real-time sync!'
            :
            'Real backend mode - Make sure backend server is running on port 8080'));
  };

  const generateRoomId = () => {
    return 'ROOM-' + Math.random().toString(36).substr(2, 6).toUpperCase();
  };

  const createRoom = async () => {
    if (!username.trim()) {
      alert('✨ Please enter your name to continue!');
      return;
    }

    setIsCreating(true);
    
    if (useMockMode) {
      // Mock mode - create room locally
      const newRoomId = generateRoomId();
      const userId = 'user-' + Math.random().toString(36).substr(2, 8);
      
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', 'HOST');
      localStorage.setItem('useMockMode', 'true');
      
      alert(`🎉 Room Created Successfully!\n\nRoom Code: ${newRoomId}\n\nShare this code with friends to join!\nThey can open this app in another tab and use "Join Party" with this code.`);
      
      navigate(`/room/${newRoomId}`);
      setIsCreating(false);
      return;
    }

    // Real backend mode
    try {
      const response = await fetch('http://localhost:8080/api/rooms/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username }),
      });

      const data = await response.json();
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', data.role);
      localStorage.setItem('useMockMode', 'false');
      navigate(`/room/${data.roomId}`);
    } catch (error) {
      console.error('Error creating room:', error);
      alert('⚠️ Backend server not found!\n\nPlease start the backend server or enable Mock Mode.');
    } finally {
      setIsCreating(false);
    }
  };

  const joinRoom = async () => {
    if (!username.trim()) {
      alert('✨ Please enter your name first!');
      return;
    }
    if (!roomCode.trim()) {
      alert('🔑 Please enter a room code to join!');
      return;
    }

    setIsJoining(true);
    
    if (useMockMode) {
      // Mock mode - join existing room
      const userId = 'user-' + Math.random().toString(36).substr(2, 8);
      
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', 'PARTICIPANT');
      localStorage.setItem('useMockMode', 'true');
      
      navigate(`/room/${roomCode.toUpperCase()}`);
      setIsJoining(false);
      return;
    }

    // Real backend mode
    try {
      const response = await fetch('http://localhost:8080/api/rooms/join', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ roomId: roomCode, username }),
      });

      if (!response.ok) {
        throw new Error('Room not found');
      }

      const data = await response.json();
      localStorage.setItem('userId', data.userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', data.role);
      localStorage.setItem('useMockMode', 'false');
      navigate(`/room/${roomCode}`);
    } catch (error) {
      console.error('Error joining room:', error);
      alert('❌ Room not found. Please check the room code and try again!');
    } finally {
      setIsJoining(false);
    }
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '20px' }}>
          <button
            onClick={toggleMockMode}
            style={{
              background: useMockMode ? '#4caf50' : '#9e9e9e',
              color: 'white',
              border: 'none',
              borderRadius: '20px',
              padding: '5px 15px',
              fontSize: '12px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
          >
            {useMockMode ? '🎮 Mock Mode ON' : '🔌 Real Mode OFF'}
          </button>
        </div>

        <h1>🎬 YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!<br />Sync, chat, and enjoy together! 🚀</p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="✨ Enter your awesome name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && createRoom()}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating}
          >
            {isCreating ? (
              <>
                <span className="loading"></span> Creating...
              </>
            ) : (
              '✨ Create New Party'
            )}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="🔑 Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
              onKeyPress={(e) => e.key === 'Enter' && joinRoom()}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining}
            >
              {isJoining ? (
                <>
                  <span className="loading"></span> Joining...
                </>
              ) : (
                '🚪 Join Party'
              )}
            </button>
          </div>
        </div>

        <div className="features">
          <div className="feature-badge">Real-time Sync</div>
          <div className="feature-badge">Role-based Access</div>
          <div className="feature-badge">Live Chat</div>
          <div className="feature-badge">YouTube Integration</div>
        </div>

        <div style={{ marginTop: '20px', padding: '10px', background: '#f0f0f0', borderRadius: '10px', fontSize: '12px' }}>
          <strong>💡 Testing Instructions:</strong><br/>
          1. Open this app in TWO browser tabs/windows<br/>
          2. In Tab 1: Enter name and click "Create New Party"<br/>
          3. Copy the Room Code shown<br/>
          4. In Tab 2: Enter different name, paste Room Code, click "Join Party"<br/>
          5. Watch real-time sync between tabs! 🎉
        </div>
      </div>
    </div>
  );
};

export default Home;
